// Arma el pedido para OpenAI con el historial de la conversación
const cfg = $('Configuracion').first().json;
const ev  = $('Llega una consulta').first().json.body || {};

const historial = Array.isArray(ev.historial) ? ev.historial.slice(-8) : [];
const pregunta  = (ev.pregunta || '').toString().slice(0, 1000);

if (!pregunta.trim()) {
  return [{ json: { vacio: true } }];
}

const mensajes = [
  { role: 'system', content: cfg.conocimiento }
];
historial.forEach(m => {
  if (m && m.rol && m.texto) {
    mensajes.push({ role: m.rol === 'bot' ? 'assistant' : 'user', content: String(m.texto).slice(0, 1000) });
  }
});
mensajes.push({ role: 'user', content: pregunta });

return [{ json: {
  mensajes,
  pregunta,
  // el user_id sale del token validado por Supabase, nunca del cuerpo del pedido
  userId: $('Ver quien pregunta').first().json.id || null,
  modo: ev.modo || null
} }];

// Saca la respuesta y decide si hay que avisarle a Agustín
const salida = $input.first().json;
const ctx    = $('Armar conversacion').first().json;

let respuesta = '';
try {
  respuesta = salida.choices[0].message.content.trim();
} catch (e) {
  respuesta = 'Ahora mismo no puedo responderte. Probá en un rato o escribinos y te contestamos.';
}

// Si el bot no supo o el tema es delicado, queda registrado para revisar
const derivar = /no s[eé]|equipo|no puedo|reclamo|cobro|pago|estafa|problema con mi cuenta/i.test(respuesta + ' ' + ctx.pregunta);

return [{ json: {
  respuesta,
  derivar,
  pregunta: ctx.pregunta,
  userId: ctx.userId,
  modo: ctx.modo
} }];
